COMMENT ON COLUMN therapists.upi_id IS 'UPI ID for salary';

-- ======== 006_customer_plans.sql ========
-- Prepaid customer plans: one balance is either hours or INR, never both.
CREATE TABLE customer_plans (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id BIGINT NOT NULL REFERENCES customers(id),
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  name TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  plan_type TEXT NOT NULL CHECK (plan_type IN ('hours', 'rupees')),
  purchased_amount NUMERIC(12,2) NOT NULL CHECK (purchased_amount > 0),
  balance NUMERIC(12,2) NOT NULL CHECK (balance >= 0 AND balance <= purchased_amount),
  expires_on DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX customer_plans_customer_idx ON customer_plans (spa_id, customer_id, created_at);

CREATE TABLE plan_redemptions (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plan_id BIGINT NOT NULL REFERENCES customer_plans(id),
  appointment_id BIGINT NOT NULL REFERENCES appointments(id),
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  unit TEXT NOT NULL CHECK (unit IN ('hours', 'rupees')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  reversed_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX plan_redemptions_one_active_appointment
  ON plan_redemptions (appointment_id) WHERE reversed_at IS NULL;
CREATE INDEX plan_redemptions_plan_idx ON plan_redemptions (plan_id, created_at);

COMMENT ON TABLE customer_plans IS 'Prepaid package owned by one customer in one spa. A balance is measured in hours or INR.';
COMMENT ON COLUMN customer_plans.id IS 'Identity.';
COMMENT ON COLUMN customer_plans.customer_id IS 'Customer who purchased this plan.';
COMMENT ON COLUMN customer_plans.spa_id IS 'Owning spa; must match the customer and appointment.';
COMMENT ON COLUMN customer_plans.name IS 'Display name of the prepaid package.';
COMMENT ON COLUMN customer_plans.plan_type IS 'Balance unit: hours for service time, or rupees for service value.';
COMMENT ON COLUMN customer_plans.purchased_amount IS 'Original amount purchased, in the plan unit.';
COMMENT ON COLUMN customer_plans.balance IS 'Remaining amount, in the plan unit; reduced only when an appointment is completed.';
COMMENT ON COLUMN customer_plans.expires_on IS 'Optional last date on which this plan can be redeemed.';
COMMENT ON COLUMN customer_plans.notes IS 'Optional purchase or package notes.';
COMMENT ON COLUMN customer_plans.created_at IS 'When the plan was added to the customer.';

COMMENT ON TABLE plan_redemptions IS 'Auditable deductions from prepaid customer plans for completed appointments; reversal restores the balance.';
COMMENT ON COLUMN plan_redemptions.id IS 'Identity.';
COMMENT ON COLUMN plan_redemptions.plan_id IS 'The prepaid plan that paid for the appointment.';
COMMENT ON COLUMN plan_redemptions.appointment_id IS 'The completed appointment; only one active plan deduction per appointment.';
COMMENT ON COLUMN plan_redemptions.spa_id IS 'Owning spa for tenant isolation.';
COMMENT ON COLUMN plan_redemptions.amount IS 'Amount deducted in the unit recorded alongside it.';
COMMENT ON COLUMN plan_redemptions.unit IS 'hours or rupees, matching the plan type.';
COMMENT ON COLUMN plan_redemptions.created_at IS 'When the appointment consumed the plan.';
COMMENT ON COLUMN plan_redemptions.reversed_at IS 'When a deduction was reversed because the appointment left completed status.';

-- ======== 007_therapist_shifts.sql ========
-- Reusable shift templates and a therapist's weekly shift assignment.
-- day_of_week uses ISO numbering: Monday=0 through Sunday=6.
CREATE TABLE shifts (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  name TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  start_time TIME NOT NULL,
  end_time TIME NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (start_time < end_time)
);
CREATE UNIQUE INDEX shifts_spa_name_idx ON shifts (spa_id, lower(name));

CREATE TABLE therapist_shift_assignments (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  therapist_id BIGINT NOT NULL REFERENCES therapists(id),
  shift_id BIGINT NOT NULL REFERENCES shifts(id),
  day_of_week SMALLINT NOT NULL CHECK (day_of_week BETWEEN 0 AND 6),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (spa_id, therapist_id, day_of_week)
);
CREATE INDEX therapist_shift_assignments_therapist_idx
  ON therapist_shift_assignments (spa_id, therapist_id, day_of_week);

COMMENT ON TABLE shifts IS 'Reusable daily work-time window for a spa.';
COMMENT ON COLUMN shifts.start_time IS 'Local shift start time; shifts do not cross midnight.';
COMMENT ON COLUMN shifts.end_time IS 'Local shift end time; must be later than start_time.';
COMMENT ON TABLE therapist_shift_assignments IS 'Weekly therapist roster; one shift per weekday. Monday=0 through Sunday=6.';
COMMENT ON COLUMN therapist_shift_assignments.day_of_week IS 'ISO weekday number: Monday 0, Tuesday 1, ..., Sunday 6.';

COMMENT ON COLUMN shifts.id IS 'Identity.';
COMMENT ON COLUMN shifts.spa_id IS 'Owning spa; shift templates are tenant-scoped.';
COMMENT ON COLUMN shifts.name IS 'Display name of the reusable work-time window.';
COMMENT ON COLUMN shifts.is_active IS 'Inactive shifts cannot be assigned to therapists.';
COMMENT ON COLUMN shifts.created_at IS 'When the shift template was created.';
COMMENT ON COLUMN therapist_shift_assignments.id IS 'Identity.';
COMMENT ON COLUMN therapist_shift_assignments.spa_id IS 'Owning spa; must match the therapist and shift.';
COMMENT ON COLUMN therapist_shift_assignments.therapist_id IS 'Therapist assigned to this weekly shift.';
COMMENT ON COLUMN therapist_shift_assignments.shift_id IS 'Reusable shift template assigned for this weekday.';
COMMENT ON COLUMN therapist_shift_assignments.created_at IS 'When the weekly assignment was created.';

-- ======== 008_plan_topups.sql ========
-- Top-ups add to an existing prepaid plan; each one is kept so sales reports count it in its own period.
CREATE TABLE plan_topups (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plan_id BIGINT NOT NULL REFERENCES customer_plans(id),
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  note TEXT,
  created_by BIGINT REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX plan_topups_spa_time_idx ON plan_topups (spa_id, created_at);
CREATE INDEX plan_topups_plan_idx ON plan_topups (plan_id, created_at);
COMMENT ON TABLE plan_topups IS 'Amounts added to an existing prepaid plan after it was sold.';
COMMENT ON COLUMN plan_topups.id IS 'Identity.';
COMMENT ON COLUMN plan_topups.plan_id IS 'Plan that was topped up.';
COMMENT ON COLUMN plan_topups.spa_id IS 'Owning spa; same as the plan.';
COMMENT ON COLUMN plan_topups.amount IS 'Amount added, in the plan unit (hours or rupees).';
COMMENT ON COLUMN plan_topups.note IS 'Optional note, e.g. payment details.';
COMMENT ON COLUMN plan_topups.created_by IS 'Login that added the top-up.';
COMMENT ON COLUMN plan_topups.created_at IS 'When the top-up was added.';

-- ======== 009_plan_price_paid.sql ========
-- What the customer actually paid for a plan or a top-up, so plan sales count as revenue.
ALTER TABLE customer_plans ADD COLUMN IF NOT EXISTS price_paid NUMERIC(12,2) CHECK (price_paid >= 0);
ALTER TABLE plan_topups ADD COLUMN IF NOT EXISTS price_paid NUMERIC(12,2) CHECK (price_paid >= 0);
-- rupee plans: paid what was loaded; hours plans sold before this have no known price (counted as 0)
UPDATE customer_plans p SET price_paid = p.purchased_amount
       - COALESCE((SELECT SUM(x.amount) FROM plan_topups x WHERE x.plan_id = p.id), 0)
 WHERE p.price_paid IS NULL AND p.plan_type = 'rupees';
UPDATE plan_topups x SET price_paid = x.amount FROM customer_plans p
 WHERE p.id = x.plan_id AND x.price_paid IS NULL AND p.plan_type = 'rupees';
COMMENT ON COLUMN customer_plans.price_paid IS 'Money received when the plan was sold (INR); counted as revenue on the sale date.';
COMMENT ON COLUMN plan_topups.price_paid IS 'Money received for this top-up (INR); counted as revenue on the top-up date.';

